import { createClient } from '@/utils/supabase/server'
import Link from 'next/link'
import { getSportsList, getUnassignedCadets } from './actions'

export default async function SportsDashboard() {
  // Determine current season roughly by month (simple logic)
  const month = new Date().getMonth()
  let currentSeason = 'Fall'
  if (month >= 10 || month <= 2) currentSeason = 'Winter'
  if (month >= 2 && month <= 5) currentSeason = 'Spring'

  const sports = await getSportsList()
  
  // Group by season
  const seasons = { Fall: [], Winter: [], Spring: [] } as any
  sports.forEach(s => seasons[s.season]?.push(s))

  return (
    <div className="max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Sports Management</h1>
      
      {/* Current Season Highlight */}
      <div className="mb-10">
        <h2 className="text-xl font-bold text-indigo-600 dark:text-indigo-400 border-b border-indigo-200 pb-2 mb-4">
            Current Season: {currentSeason}
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {seasons[currentSeason]?.map((sport: any) => (
                <Link key={sport.id} href={`/sports/${sport.id}`} className="block p-6 bg-white dark:bg-gray-800 rounded-lg shadow hover:shadow-md transition border border-gray-200 dark:border-gray-700">
                    <h3 className="font-bold text-lg text-gray-900 dark:text-white">{sport.name}</h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">Manage Roster &rarr;</p>
                </Link>
            ))}
        </div>
      </div>

      {/* Other Seasons */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {Object.entries(seasons).map(([season, list]: [string, any]) => (
            season !== currentSeason && (
                <div key={season}>
                    <h3 className="font-bold text-gray-500 uppercase tracking-wider mb-3">{season} Sports</h3>
                    <ul className="space-y-2">
                        {list.map((s: any) => (
                            <li key={s.id}>
                                <Link href={`/sports/${s.id}`} className="text-indigo-600 dark:text-indigo-400 hover:underline">
                                    {s.name}
                                </Link>
                            </li>
                        ))}
                    </ul>
                </div>
            )
        ))}
      </div>
    </div>
  )
}